class School:
    def __init__(self):
        self._grades = {}
        self._students = set()
        self._added = []

    def add_student(self, name, grade):
        if name in self._students:
            self._added.append(False)
            return False
        self._students.add(name)
        self._grades.setdefault(grade, set()).add(name)
        self._added.append(True)
        return True

    def roster(self):
        students = []
        for grade_number in sorted(self._grades):
            students.extend(sorted(self._grades[grade_number]))
        return students

    def grade(self, grade_number):
        return sorted(self._grades.get(grade_number, set()))

    def added(self):
        return list(self._added)
